import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ProfService } from 'src/app/core/services/prof.service';

@Component({
  selector: 'app-join-class',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './join-class.component.html',
  styleUrls: ['./join-class.component.scss']
})
export class JoinClassComponent implements OnInit {
  code = '';
  classData: any = null;
  msg = '';
  loading = false;
  profSlug: string | null = null;

  constructor(
    private route: ActivatedRoute,
    private profService: ProfService,
    private router: Router
  ) {}

  ngOnInit() {
    // Récupère le slug du prof (optionnel)
    this.profSlug = this.route.snapshot.queryParamMap.get('prof');

    // Si le code est déjà passé (ex: ?code=CL-123456)
    const queryCode = this.route.snapshot.queryParamMap.get('code');
    if (queryCode) {
      this.code = queryCode;
      this.join();
    }
  }

  join() {
    if (!this.code.trim()) {
      this.msg = '⚠️ Code requis';
      return;
    }

    this.loading = true;
    this.profService.getClassByCode(this.code).subscribe({
      next: (res: any) => {
        this.loading = false;
        if (res && res.id) {
          this.classData = res;
          // Redirige vers la page des fichiers de cette classe
          this.router.navigate(['/student/class', res.id]);
        } else {
          this.msg = '❌ Classe introuvable';
        }
      },
      error: (err: any) => {
        console.error('Erreur recherche classe:', err);
        this.msg = '❌ Classe introuvable';
        this.loading = false;
      }
    });
  }
}
<section class="student-home container py-5">
  <h1 class="text-center fw-bold mb-4">Rejoindre une classe</h1>
  <p class="text-center text-muted mb-5">Entrez le code fourni par votre professeur pour accéder à votre classe.</p>

  <form (ngSubmit)="join()" class="card p-4 shadow-sm mx-auto" style="max-width:500px">
    <div class="mb-3">
      <label class="form-label">Code d’accès</label>
      <input type="text" [(ngModel)]="code" name="code" class="form-control" placeholder="Ex : CL-AB12CD" required>
    </div>

    <button type="submit" class="btn btn-primary w-100">Rejoindre</button>
    <p class="text-center mt-2 text-danger">{{ msg }}</p>
  </form>

  <div *ngIf="loading" class="text-center my-4">
    <div class="spinner-border text-primary"></div>
  </div>

  <div *ngIf="classData" class="card p-4 shadow-sm mt-4">
    <h4 class="fw-bold text-primary">{{ classData.name }}</h4>
    <p class="text-muted mb-1">{{ classData.description }}</p>
    <p><strong>Code :</strong> {{ classData.accessCode }}</p>
    <p><strong>Créée le :</strong> {{ classData.createdAt | date:'short' }}</p>
  </div>
</section>
